'use strict';

(function installLinuxOverlay() {
  function ready(fn) {
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', fn, { once: true });
    else fn();
  }

  ready(() => {
    if (!window.ipcRenderer || document.getElementById('dc-linux-bridge')) return;

    const invoke = window.ipcRenderer.invoke.bind(window.ipcRenderer);
    let presetConfig = null;
    let timer = null;
    let active = false;
    let currentMode = null; // 'preset' | 'preview' | 'image'
    let lastFrameDataUrl = null; // 唯一渲染源：软件预览与 LCD 共用
    let previewStarting = false; // 防并发截图（capturePage 并发会挂起）
    let zenActive = false;       // 待机状态：自动预览不打扰
    let lastBrightness = null;   // 官方亮度控制（0-100，软遮罩）


    function fieldValue(status, name) {
      const s = status && status.snapshot ? status.snapshot : {};
      const round = (n, d = 1) => {
        const v = Number(n);
        if (!Number.isFinite(v)) return 0;
        const p = 10 ** d;
        return Math.round(v * p) / p;
      };
      switch (String(name || '').toLowerCase()) {
        case 'cpu temperature': case 'cpu temp': return { v: round(s.cpu_temp), u: '°C', big: true };
        case 'cpu frequency': case 'cpu freq': return { v: round(Number(s.cpu_freq) || 0, 1), u: 'GHz', big: false };
        case 'cpu power': return { v: round(s.cpu_power, 0), u: 'W', big: false };
        case 'cpu load': case 'cpu usage': return { v: round(s.cpu_usage), u: '%', big: false };
        case 'gpu temperature': case 'gpu temp': return { v: round(s.gpu_temp), u: '°C', big: true };
        case 'gpu power': return { v: round(s.gpu_power, 0), u: 'W', big: false };
        case 'gpu usage': case 'gpu load': return { v: round(s.gpu_usage), u: '%', big: false };
        case 'gpu memory': case 'gpu mem': case '显存': return { v: `${round(s.gpu_mem_used / 1073741824, 1)}/${round(s.gpu_mem_total / 1073741824, 1)}`, u: 'G', big: false };
        case 'ram': case 'ram usage': case 'memory usage':
        case 'memory load': case '内存负载': return { v: round(s.mem_percent), u: '%', big: false };
        case 'time': return { v: s.local_time || '--:--', u: '', big: false };
        default: return { v: '--', u: '', big: false };
      }
    }

    // ===== 官方 L122 数字模式渲染（反编译自 DeepCool 1.2.12）=====
    // 背景图：assets/horizontal_bg-3de67705.png / vertical_bg-9219be0f.png
    // 图标：cpu_icon / gpu_icon / ram_icon；字体：JZFS-Sans（官方嵌入字体）
    const BG_H = "data:image/png;base64,";
    const BG_V = "data:image/png;base64,";
    const ICONS = {
      cpu_icon: "'''+icons['cpu_icon']+'''",
      gpu_icon: "'''+icons['gpu_icon']+'''",
      ram_icon: "'''+icons['ram_icon']+'''"
    };
    const OFFICIAL_FONT = 'JZFS-Sans'; // 官方 LCD 数字字体（嵌入 app.asar）

    const officialPosition = {
      horizontal: {
        mainData: { valueX: 29, valueY: 119, unitOffsetLeft: 6, unitOffsetTop: 17.5, iconX: 29, iconY: 151.5, textX: 51, textY: 160.5, blockX: 179, blockY: 51 },
        subData1: { valueX: 211, valueY: 59.5, unitOffsetLeft: 4, unitOffsetTop: 9, iconX: 211, iconY: 84, textX: 233, textY: 94.5 },
        subData2: { valueX: 211, valueY: 167.5, unitOffsetLeft: 4, unitOffsetTop: 9, iconX: 211, iconY: 192, textX: 233, textY: 202.55 },
        time: { valueX: 22, valueY: 119 }
      },
      vertical: {
        mainData: { valueX: 119, valueY: 107.5, unitOffsetLeft: 6, unitOffsetTop: 17.5, iconX: 84, iconY: 141, textX: 106, textY: 151.5, blockX: 209, blockY: 41 },
        subData1: { valueX: 23, valueY: 252.5, unitOffsetLeft: 4, unitOffsetTop: 9, iconX: 23, iconY: 275, textX: 45, textY: 285.5 },
        subData2: { valueX: 135, valueY: 252.5, unitOffsetLeft: 4, unitOffsetTop: 9, iconX: 135, iconY: 275, textX: 157, textY: 285.5 },
        time: { valueX: 42, valueY: 107 }
      }
    };
    const officialStyle = {
      mainData: { valueSize: 70, valueColor: '#ffffff', valueWeight: 300, unitSize: 16, unitColor: '#ffffff', unitWeight: 300, textSize: 10, textColor: 'rgba(255,255,255,0.7)', textWeight: 300 },
      subData1: { valueSize: 40, valueColor: '#ffffff', valueWeight: 200, unitSize: 12, unitColor: '#ffffff', unitWeight: 400, textSize: 10, textColor: 'rgba(255,255,255,0.7)', textWeight: 300 },
      subData2: { valueSize: 40, valueColor: '#ffffff', valueWeight: 200, unitSize: 12, unitColor: '#ffffff', unitWeight: 400, textSize: 10, textColor: 'rgba(255,255,255,0.7)', textWeight: 300 },
      time: { size: 60, weight: 300, hourColor: '#ffffff', hourWeight: 400, minColor: '#6CD7E1' }
    };

    function officialText(ctx, text, x, y, fontSize, fontColor, fontWeight = 'normal', textAlign = 'left') {
      ctx.font = `${fontWeight} ${fontSize}px ${OFFICIAL_FONT}`;
      ctx.fillStyle = fontColor;
      ctx.textAlign = textAlign;
      ctx.textBaseline = 'middle';
      ctx.fillText(text, x, y);
    }

    function officialGetWidth(ctx, text, fontSize, fontWeight = 'normal') {
      ctx.font = `${fontWeight} ${fontSize}px ${OFFICIAL_FONT}`;
      return ctx.measureText(text).width;
    }

    function officialData(type, value, unit) {
      const base = { value, unit };
      switch (type) {
        case 'CPU Temperature': return { text: 'CPU TEMP', icon: 'cpu_icon', block: true, ...base };
        case 'CPU Load': return { text: 'CPU Load', icon: 'cpu_icon', block: true, ...base };
        case 'Time': return { text: 'time', icon: 'cpu_icon', block: false, ...base };
        case 'GPU Temperature': return { text: 'GPU TEMP', icon: 'gpu_icon', block: true, ...base };
        case 'GPU Power': return { text: 'GPU Power', icon: 'gpu_icon', block: true, ...base };
        case 'CPU Power': return { text: 'CPU Power', icon: 'cpu_icon', block: true, ...base };
        case 'CPU Frequency': return { text: 'CPU FREQ', icon: 'cpu_icon', block: true, ...base };
        case 'Memory Load': return { text: 'Memory Load', icon: 'ram_icon', block: true, ...base };
        default: return { text: 'Other', icon: 'cpu_icon', block: false, ...base };
      }
    }

    // 预加载官方资源
    const officialAssets = { horizontal: new Image(), vertical: new Image(), cpu_icon: new Image(), gpu_icon: new Image(), ram_icon: new Image() };
    officialAssets.horizontal.src = BG_H;
    officialAssets.vertical.src = BG_V;
    officialAssets.cpu_icon.src = ICONS.cpu_icon;
    officialAssets.gpu_icon.src = ICONS.gpu_icon;
    officialAssets.ram_icon.src = ICONS.ram_icon;
    // 官方 JZFS-Sans 字体只在 L122 页面 chunk CSS 中注册；首页/自动恢复时未加载，
    // 会导致 canvas 回退系统字体。这里主动注入 @font-face（与官方同源文件）。
    function ensureOfficialFont() {
      try {
        if (!document.fonts.check('16px "JZFS-Sans"')) {
          const style = document.createElement('style');
          style.textContent = `@font-face { font-family: 'JZFS-Sans'; src: url('./assets/JZFSSans-Light-ea2a1e77.otf') format('opentype'); font-weight: 100 900; }`;
          document.head.appendChild(style);
        }
      } catch (_) {}
    }
    ensureOfficialFont();
    async function ensureFontsReady() {
      try { await document.fonts.load('300 70px JZFS-Sans'); } catch (_) {}
      try { await document.fonts.load('200 40px JZFS-Sans'); } catch (_) {}
      try { await document.fonts.load('300 10px JZFS-Sans'); } catch (_) {}
      try { await document.fonts.ready; } catch (_) {}
    }

    function drawOfficialPreset(config, status) {
      const canvas = document.createElement('canvas');
      canvas.width = 320; canvas.height = 240;
      const ctx = canvas.getContext('2d');
      ctx.translate(0.5, 0.5);
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = 'high';

      const d = (config && config.digitalData) || {};
      const orientation = Number(d.orientation) || 0;
      const horizontal = orientation === 0 || orientation === 180;
      const w = horizontal ? 320 : 240;
      const h = horizontal ? 240 : 320;
      canvas.width = w; canvas.height = h;
      // 旋转（官方 0/180 横屏，90/270 竖屏）
      ctx.translate(w / 2, h / 2);
      ctx.rotate(orientation === 180 ? Math.PI : orientation === 90 ? Math.PI / 2 : orientation === 270 ? -Math.PI / 2 : 0);
      ctx.translate(-w / 2, -h / 2);

      // 背景图
      const bg = horizontal ? officialAssets.horizontal : officialAssets.vertical;
      if (bg && bg.complete && bg.naturalWidth > 0) {
        ctx.drawImage(bg, 0, 0, w, h);
      } else {
        ctx.fillStyle = '#0a0f18';
        ctx.fillRect(0, 0, w, h);
      }

      const pos = officialPosition[horizontal ? 'horizontal' : 'vertical'];
      const style = officialStyle;
      const fields = [d.mainData, d.subData1, d.subData2].filter(Boolean);
      const vals = fields.map((f) => fieldValue(status, f));
      const main = officialData(fields[0], vals[0].v, vals[0].u);
      const sub1 = officialData(fields[1], vals[1].v, vals[1].u);
      const sub2 = officialData(fields[2], vals[2].v, vals[2].u);

      const drawMain = (data) => {
        const p = pos.mainData; const st = style.mainData;
        // 温度主数据显示整数（避免 48.6 这类带小数在 70px 下超出边界）
        if ((data.text === 'CPU TEMP' || data.text === 'GPU TEMP') && data.value !== '' && !Number.isNaN(Number(data.value))) {
          data.value = String(Math.round(Number(data.value)));
        }
        // 主数据可用区域：横屏 [valueX, blockX]，竖屏 [valueX, 画布右缘]
        const mainLeft = p.valueX;
        const mainRight = horizontal ? p.blockX : canvas.width - 10;
        const mainCenterX = (mainLeft + mainRight) / 2;
        const maxMainWidth = mainRight - mainLeft - 10;
        // 自适应缩放：保证 数值+单位 不超出主区域
        let fs = st.valueSize;
        let unitFs = st.unitSize;
        while (fs > 28 &&
               officialGetWidth(ctx, data.value, fs, st.valueWeight) + officialGetWidth(ctx, data.unit, unitFs, st.unitWeight) + 8 > maxMainWidth) {
          fs -= 2;
          unitFs = Math.max(10, unitFs - 1);
        }
        // 整体（数值+单位）在主区域内水平居中
        const valueWidth = officialGetWidth(ctx, data.value, fs, st.valueWeight);
        const unitWidth = officialGetWidth(ctx, data.unit, unitFs, st.unitWeight);
        const totalWidth = valueWidth + p.unitOffsetLeft + unitWidth;
        const startX = mainCenterX - totalWidth / 2;
        officialText(ctx, data.value, startX, p.valueY, fs, st.valueColor, st.valueWeight);
        officialText(ctx, data.unit, startX + valueWidth + p.unitOffsetLeft, p.valueY + p.unitOffsetTop, unitFs, st.unitColor, st.unitWeight);
        // 下方文字描述（+图标）整体在主区域内水平居中
        const iconW = 20;
        const iconGap = 6;
        const labelTextW = officialGetWidth(ctx, data.text, st.textSize, st.textWeight);
        const hasIcon = data.icon && officialAssets[data.icon] && officialAssets[data.icon].complete && officialAssets[data.icon].naturalWidth > 0;
        const labelTotalW = (hasIcon ? iconW + iconGap : 0) + labelTextW;
        const labelStartX = mainCenterX - labelTotalW / 2;
        const icon = officialAssets[data.icon];
        if (hasIcon) ctx.drawImage(icon, labelStartX, p.iconY, iconW, iconW);
        officialText(ctx, data.text, labelStartX + (hasIcon ? iconW + iconGap : 0), p.textY, st.textSize, st.textColor, st.textWeight);
        if (data.block && p.blockX !== undefined) {
          const bars = Math.ceil(Number(data.value) / 20);
          drawOfficialProgress(ctx, p.blockX, p.blockY, bars, 5);
        }
      };
      const drawSide = (data, key) => {
        const p = pos[key]; const st = style[key];
        // 副数据区域边界（横屏 211~310；竖屏 sub1 23~127、sub2 135~229）
        let sideLeft, sideRight;
        if (horizontal) {
          sideLeft = p.valueX; sideRight = canvas.width - 10;
        } else {
          sideLeft = p.valueX;
          sideRight = key === 'subData1' ? 127 : 229;
        }
        const sideCenterX = (sideLeft + sideRight) / 2;
        const maxSideWidth = sideRight - sideLeft - 8;
        // 自适应缩放：数值+单位不超出副数据区域
        let fs = st.valueSize;
        let unitFs = st.unitSize;
        while (fs > 20 &&
               officialGetWidth(ctx, data.value, fs, st.valueWeight) + officialGetWidth(ctx, data.unit, unitFs, st.unitWeight) + 6 > maxSideWidth) {
          fs -= 2;
          unitFs = Math.max(8, unitFs - 1);
        }
        // 数值+单位整体在区域内居中
        const valueWidth = officialGetWidth(ctx, data.value, fs, st.valueWeight);
        const unitWidth = officialGetWidth(ctx, data.unit, unitFs, st.unitWeight);
        const totalWidth = valueWidth + p.unitOffsetLeft + unitWidth;
        const startX = sideCenterX - totalWidth / 2;
        officialText(ctx, data.value, startX, p.valueY, fs, st.valueColor, st.valueWeight);
        officialText(ctx, data.unit, startX + valueWidth + p.unitOffsetLeft, p.valueY + p.unitOffsetTop, unitFs, st.unitColor, st.unitWeight);
        // 图标+文字描述也在区域内居中
        const iconW = 20;
        const iconGap = 6;
        const labelTextW = officialGetWidth(ctx, data.text, st.textSize, st.textWeight);
        const hasIcon = data.icon && officialAssets[data.icon] && officialAssets[data.icon].complete && officialAssets[data.icon].naturalWidth > 0;
        const labelTotalW = (hasIcon ? iconW + iconGap : 0) + labelTextW;
        const labelStartX = sideCenterX - labelTotalW / 2;
        const icon = officialAssets[data.icon];
        if (hasIcon) ctx.drawImage(icon, labelStartX, p.iconY, iconW, iconW);
        officialText(ctx, data.text, labelStartX + (hasIcon ? iconW + iconGap : 0), p.textY, st.textSize, st.textColor, st.textWeight);
      };
      drawMain(main);
      drawSide(sub1, 'subData1');
      drawSide(sub2, 'subData2');
      return canvas;
    }

    function drawPreset(config, status) {
      // 使用官方 L122 数字模式渲染（背景/图标/坐标/字体与官方一致）
      return drawOfficialPreset(config, status);
    }

    function drawOfficialProgress(ctx, x, y, bars, size) {
      // 官方进度条：按 20% 一格的方块；竖屏时收敛起点防越界（画布宽 240）
      const maxX = ctx.canvas ? ctx.canvas.width : 320;
      const startX = Math.min(x, maxX - 5 * (size + 3) + 3);
      for (let i = 0; i < 5; i++) {
        const on = i < bars;
        ctx.fillStyle = on ? '#6CD7E1' : 'rgba(255,255,255,0.12)';
        ctx.fillRect(startX + i * (size + 3), y, size, size);
      }
    }


    // 官方亮度滑块是软遮罩：opacity = 1 - (brightness + 70) / 170
    // （brightness=0 最暗，=100 最亮）。推屏前应用到画布，LCD 与软件预览一致。
    function applyBrightness(canvas) {
      if (lastBrightness === null || lastBrightness === undefined) return;
      const b = Number(lastBrightness);
      if (!Number.isFinite(b)) return;
      const opacity = Math.max(0, Math.min(1, 1 - (b + 70) / 170));
      if (opacity <= 0) return;
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = `rgba(0,0,0,${opacity.toFixed(4)})`;
      ctx.fillRect(0, 0, canvas.width, canvas.height);
    }

    async function pushCanvas(canvas) {
      applyBrightness(canvas);
      const dataUrl = canvas.toDataURL('image/png');
      return pushDataUrl(dataUrl);
    }

    // 统一推帧入口（preset/preview/image 三路共用）：亮度遮罩、lastFrameDataUrl、
    // 推送前模式复查、in-flight 防堆叠全部在此处理。
    let frameBusy = false; // 上一帧未完成时跳过本 tick（daemon 慢时不并发堆积）
    async function pushDataUrl(dataUrl, expectedMode) {
      if (frameBusy) return false;
      frameBusy = true;
      try {
        // 推屏前复查：期间 stopLoop/startLoop 切换了模式则放弃旧帧
        if (expectedMode !== undefined && (!active || currentMode !== expectedMode)) return false;
        lastFrameDataUrl = dataUrl;
        const result = await invoke('linux/push-image', dataUrl);
        if (!result || !result.ok) throw new Error((result && result.error) || '推送失败');
        return true;
      } finally {
        frameBusy = false;
      }
    }

    async function pushFrame(mode) {
      try {
        if (frameBusy) return;
        await ensureFontsReady();
        const status = await invoke('linux/status');
        if (!active || currentMode !== mode) return;
        const canvas = drawPreset(presetConfig, status);
        if (!active || currentMode !== mode) return;
        await pushCanvas(canvas);
      } catch (error) {
        console.error('[DeepCool Linux] frame push failed:', error);
      }
    }

    function startLoop(mode) {
      stopLoop();
      zenActive = false;
      active = true;
      currentMode = mode;
      invoke('linux/hold-state', true).catch(() => {});
      pushFrame(mode);
      // 推帧周期 1 秒（LCD 每秒刷新一次）
      timer = setInterval(() => pushFrame(mode), 1000);
    }

    function stopLoop() {
      active = false;
      currentMode = null;
      if (timer) clearInterval(timer);
      timer = null;
      invoke('linux/hold-state', false).catch(() => {});
    }

    async function pushPreviewLoop() {
      if (previewStarting) return;
      previewStarting = true;
      try {
      const target = document.querySelector('.ld_right_one') || document.querySelector('.area');
      if (!target) throw new Error('请先进入 LM-Series 设备页面');
      const r = target.getBoundingClientRect();
      const dataUrl = await Promise.race([
        invoke('linux/capture-image', { x: r.x, y: r.y, width: r.width, height: r.height }),
        new Promise((_, reject) => setTimeout(() => reject(new Error('capture timeout')), 4000)),
      ]);
      // 若 await 期间已有循环激活（如用户保存预设），则放弃本次预览。
      if (active) return;
      stopLoop();
      active = true;
      currentMode = 'preview';
      invoke('linux/hold-state', true).catch(() => {});
      const push = () => pushDataUrl(dataUrl, 'preview');
      const firstOk = await push();
      // 复查模式后再建 interval：await 期间若被 startLoop 接管，不建空转 timer
      if (!firstOk || !active || currentMode !== 'preview') return;
      timer = setInterval(push, 1000);
      } finally {
        previewStarting = false;
      }
    }

    // 上传图片/编辑图片后：持续显示该图片
    function startImageLoop(dataUrl) {
      stopLoop();
      zenActive = false;
      active = true;
      currentMode = 'image';
      invoke('linux/hold-state', true).catch(() => {});
      const push = () => pushDataUrl(dataUrl, 'image');
      push();
      timer = setInterval(push, 1000);
    }

    // 统一渲染：软件预览（l122/image-transmission）直接显示最近推送到 LCD 的
    // 同一张图，不再由 main 进程生成第二套画面。
    window.ipcRenderer.invoke = async function (channel, ...args) {
      // 官方 image-transmission 期望直接返回 data URL 字符串（页面直接绑 img.src）
      if (channel === 'l122/image-transmission' && lastFrameDataUrl) {
        return lastFrameDataUrl;
      }
      // 官方"开机自启动"开关：app/set-setting {launch} → Linux XDG autostart。
      // 写文件后仍透传官方 main（Windows 桩，无害），让官方受控组件正常完成
      // 状态更新——不能短路返回，否则官方内部 model 与显示脱节，下次点击反向。
      if (channel === 'app/set-setting' && args[0] && typeof args[0] === 'object' && 'launch' in args[0]) {
        const want = args[0].launch === true || args[0].launch === 'true';
        const result = await invoke('linux/autostart-set', { enabled: want }).catch((error) => ({
          ok: false, error: error.message || String(error),
        }));
        if (!result || !result.ok) {
          return { code: 500, message: (result && result.error) || '开机自启设置失败', data: null };
        }
        return invoke(channel, ...args); // 透传官方（桩返回成功结构，官方 handler 正常收尾）
      }
      const result = await invoke(channel, ...args);
      if (channel === 'l122/modelConfigurationSearch' && result && result.data) {
        presetConfig = result.data;
        if (result.data.brightnessControl !== undefined) lastBrightness = result.data.brightnessControl;
      }
      if (channel === 'l122/modelConfigurationSet') {
        const cfg = args[0] || presetConfig;
        presetConfig = cfg;
        if (cfg && cfg.brightnessControl !== undefined) lastBrightness = cfg.brightnessControl;
        // 官方"禅状态"开关 → 待机；关闭则按 modeChange 恢复推帧。
        // 注意：切换数字/多媒体模式也会触发 modelConfigurationSet，且携带的
        // GlobalSetting.zenMode 可能残留 true（官方 store 持久化）——若刚发生过
        // 模式切换（applyModeChange），忽略该残留，避免"切模式就黑屏"。
        const justSwitchedMode = Date.now() - lastModeSwitchAt < 1500;
        if (cfg && cfg.zenMode === true && !justSwitchedMode) {
          lastModeChange = cfg ? Number(cfg.modeChange) : 0;
          enterZen();
        } else {
          // 统一走 applyModeChange：纠正 image/preview 下配置值未变导致无法回数字模式
          applyModeChange(cfg ? Number(cfg.modeChange) || 0 : 0, true);
          syncZenButton();
        }
        // 持久化，重启后自动恢复
        invoke('linux/preset-save', cfg).catch(() => {});
      }
      // 上传/编辑图片成功：显示该图片（软件预览与 LCD 同一张）
      if ((channel === 'l122/uploadSelectedMedia' || channel === 'l122/modifyMedia') && result && result.code === 0 && result.data && result.data.frameDataUrl) {
        startImageLoop(result.data.frameDataUrl);
      }
      return result;
    };

    // 检测官方"数字模式/多媒体模式"切换：官方切换是纯前端点击（不触发
    // modelConfigurationSet），在捕获阶段监听点击，命中"数字模式/多媒体模式"
    // 文本时更新 presetConfig.modeChange 并同步 LCD 显示模式。
    let lastModeChange = null;
    let lastModeSwitchAt = 0; // 最近一次模式切换时间（modelConfigurationSet 判断用）
    function applyModeChange(mc, force = false) {
      // 目标推帧形态：数字=preset；多媒体=有图则 image，否则先 preset 占位。
      // 注意：上传图片会 startImageLoop 但不改 lastModeChange——此时 lastModeChange
      // 仍可能是 0，若仅用 mc===lastModeChange 短路，再点「数字模式」会直接 return，
      // LCD 卡在 image/preview。必须结合 currentMode/active/zen 判断是否已到位。
      const wantImage = mc === 1 && !!lastFrameDataUrl;
      const alreadyOnTarget = !zenActive && active && (
        (wantImage && currentMode === 'image') ||
        (!wantImage && mc === 0 && currentMode === 'preset') ||
        (mc === 1 && !lastFrameDataUrl && currentMode === 'preset')
      );
      if (!force && mc === lastModeChange && alreadyOnTarget) return;
      lastModeChange = mc;
      lastModeSwitchAt = Date.now();
      if (presetConfig) presetConfig.modeChange = mc;
      console.log('[DeepCool Linux] modeChange:', mc, 'force=', force, 'currentMode=', currentMode);
      // 待机中切换模式：用户主动操作个性化设置 = 想看效果，自动退出待机
      // （同步清标志 + 放行 hold），再应用新模式；官方禅状态开关显示由
      // modelConfigurationSet 下次保存时同步。
      if (zenActive) {
        zenActive = false;
        invoke('linux/hold-state', false).catch(() => {});
        syncZenButton();
      }
      if (wantImage) {
        startImageLoop(lastFrameDataUrl);
      } else {
        // 数字模式，或多媒体但尚无可用帧：走官方数字布局推帧
        startLoop('preset');
      }
    }
    document.addEventListener('click', (event) => {
      // 向上多看几层：官方下拉项可能是 span 包在 div 里，或 text 含空白/子节点。
      let node = event.target;
      for (let depth = 0; node && depth < 6; depth += 1, node = node.parentElement) {
        if (!node.getAttribute && !node.textContent) continue;
        const text = String(node.textContent || '').replace(/\s+/g, ' ').trim();
        // 只匹配短标签，避免点到整页容器误触发
        if (text === '多媒体模式' || text === 'Multimedia Mode' || text === 'Multimedia') {
          applyModeChange(1, true);
          return;
        }
        if (text === '数字模式' || text === 'Digital Mode' || text === 'Digital') {
          applyModeChange(0, true);
          return;
        }
      }
    }, true); // 捕获阶段：先于官方 Vue handler

    // 推送预览集成到软件：进入 LM-Series 页面后自动把页面预览截图推送到 LCD
    // （立即生效，无需任何按钮）；离开页面或激活预设/图片后自动停止/让位。
    function ensureAutoPreview() {
      const inL122 = location.hash.includes('/devices/L122/');
      if (zenActive) return; // 待机状态：保持 LCD 关闭，不自动预览
      if (inL122) {
        if (!active && !previewStarting) pushPreviewLoop().catch(() => {});
      } else if (currentMode === 'preview') {
        stopLoop();
      }
    }
    // 重启软件后自动恢复上次保存的个性化设置（否则 LCD 只剩黑屏/纯色）
    async function restorePreset() {
      try {
        const saved = await invoke('linux/preset-load');
        if (saved && saved.digitalData && !active && !zenActive) {
          presetConfig = saved;
          if (saved.brightnessControl !== undefined) lastBrightness = saved.brightnessControl;
          lastModeChange = Number(saved.modeChange); // 恢复模式基线
          // 多媒体模式恢复图片显示；数字模式恢复预设推帧
          if (saved.modeChange === 1 && lastFrameDataUrl) {
            startImageLoop(lastFrameDataUrl);
          } else {
            startLoop('preset');
          }
          console.log('[DeepCool Linux] restored preset:', saved.digitalData, 'modeChange:', saved.modeChange);
        }
      } catch (error) {
        console.error('[DeepCool Linux] restore preset failed:', error);
      }
    }
    setTimeout(restorePreset, 1800);

    setTimeout(ensureAutoPreview, 1200);
    setInterval(ensureAutoPreview, 1000);

    // ---- Linux 控制浮层（精简）：官方 UI 已含"禅状态/开机自启动"开关，
    // 浮层只保留快捷待机按钮 + 状态点。 ----
    const root = document.createElement('div');
    root.id = 'dc-linux-bridge';
    root.innerHTML = `
      <button data-act="zen" title="让 LCD 进入待机（再点恢复）">待机</button>
      <span class="dc-linux-dot" title="Linux bridge 状态"></span>
    `;
    const zenBtn = root.querySelector('button[data-act="zen"]');
    function syncZenButton() {
      zenBtn.textContent = zenActive ? '恢复' : '待机';
      zenBtn.title = zenActive ? 'LCD 待机中，点击恢复' : '让 LCD 进入待机（再点恢复）';
    }
    const style = document.createElement('style');
    style.textContent = `
      #dc-linux-bridge{position:fixed;right:18px;bottom:16px;z-index:2147483647;display:flex;gap:7px;align-items:center;padding:7px 9px;border:1px solid rgba(53,224,255,.28);border-radius:11px;background:rgba(4,10,20,.9);box-shadow:0 10px 32px rgba(0,0,0,.38);backdrop-filter:blur(12px);font-family:system-ui,sans-serif}
      #dc-linux-bridge button{height:27px;padding:0 10px;border:1px solid #28405e;border-radius:7px;background:#0b1626;color:#dbe7f5;font-size:11px;cursor:pointer;transition:.15s}
      #dc-linux-bridge button:hover{border-color:#35e0ff;color:#35e0ff;background:#10243a}
      #dc-linux-bridge button:disabled{opacity:.45;cursor:wait}
      #dc-linux-bridge .dc-linux-dot{width:8px;height:8px;border-radius:50%;background:#f59e0b;box-shadow:0 0 8px currentColor}
      #dc-linux-bridge .dc-linux-dot.ok{background:#22c55e}
      #dc-linux-bridge .dc-linux-dot.bad{background:#ef4444}
    `;
    document.head.appendChild(style);
    document.body.appendChild(root);
    const dot = root.querySelector('.dc-linux-dot');

    // ---- 官方"设置 → 启动设置 → 开机自启动"开关（el-switch）桥接 ----
    // 官方开关是受控组件（不产生 DOM change），交互唯一入口是
    // invoke('app/set-setting', {launch: bool})，在下方 invoke 包装器里拦截；
    // 这里只做显示校准：进入设置页时按真实 autostart 状态覆盖开关显示。
    const OFFICIAL_SWITCH = '.setting .el-switch input';
    function officialSwitchInput() {
      return document.querySelector(OFFICIAL_SWITCH);
    }
    async function syncOfficialAutostartSwitch() {
      if (!location.hash.startsWith('#/setting')) return;
      const input = officialSwitchInput();
      if (!input) return;
      try {
        const st = await invoke('linux/autostart-status');
        if (input.checked !== st.enabled) {
          // 显示与真实状态不一致：先经官方通道把官方内部状态校准为真实值
          // （app/set-setting 会被下方拦截器幂等写文件并返回成功，官方 M 同步），
          // 再校准显示——否则官方 M 与显示脱节，用户点击会发出反向 launch。
          await invoke('app/set-setting', { launch: st.enabled });
          if (input.checked !== st.enabled) input.checked = st.enabled;
          refreshAuto(); // 浮层按钮同步
        }
      } catch (_) {}
    }

    async function refreshAuto() {
      // 浮层自启按钮已移除：autostart 状态由官方设置页开关（syncOfficialAutostartSwitch）
      // 负责显示；此处保留为空实现以兼容调用点。
      return;
    }

    async function refresh() {
      try {
        const status = await invoke('linux/status');
        dot.className = `dc-linux-dot ${status && status.ok ? 'ok' : 'bad'}`;
        dot.title = status && status.ok ? `Linux daemon: ${status.mode || 'online'}` : `Linux daemon 不可用: ${(status && status.error) || 'unknown'}`;
      } catch (error) {
        dot.className = 'dc-linux-dot bad';
        dot.title = String(error && error.message ? error.message : error);
      }
    }

    // 进入待机（Zen）：停推帧 + 置标志 + 通知 daemon。官方"禅状态"开关与
    // 浮层"待机"按钮共用此逻辑。
    async function enterZen() {
      stopLoop();
      zenActive = true;
      // 待机期间保持 hold，防止状态轮询把 daemon 切回 monitor。
      await invoke('linux/hold-state', true).catch(() => {});
      await invoke('linux/daemon-command', { action: 'zen' }).catch(() => {});
      syncZenButton();
    }

    // 退出待机：恢复推帧（预设/最近画面）。浮层"待机"按钮再点一次触发；
    // 官方"禅状态"开关关闭时由 modelConfigurationSet(zenMode:false) 走 startLoop。
    async function exitZen() {
      zenActive = false;
      await invoke('linux/hold-state', false).catch(() => {});
      if (presetConfig && presetConfig.modeChange === 1 && lastFrameDataUrl) {
        startImageLoop(lastFrameDataUrl);
      } else {
        startLoop('preset');
      }
      syncZenButton();
    }

    async function run(button, action) {
      button.disabled = true;
      const old = button.textContent;
      try {
        if (action === 'zen') {
          if (zenActive) {
            await exitZen();
          } else {
            await enterZen();
          }
        }
        button.textContent = '完成';
      } catch (error) {
        button.textContent = '失败';
        console.error('[DeepCool Linux bridge]', error);
        alert(error && error.message ? error.message : String(error));
      } finally {
        setTimeout(() => {
          if (action === 'zen') syncZenButton(); // 待机/恢复 状态按钮
          else button.textContent = old;
          button.disabled = false;
        }, 1100);
        refresh();
        refreshAuto();
      }
    }

    root.addEventListener('click', (event) => {
      const button = event.target.closest('button[data-act]');
      if (button) run(button, button.dataset.act);
    });
    refresh();
    refreshAuto();
    syncOfficialAutostartSwitch();
    setInterval(refresh, 5000);
    setInterval(refreshAuto, 5000);
    setInterval(syncOfficialAutostartSwitch, 2000);

    window.__dcPresetDebug = {
      active: () => active,
      timer: () => !!timer,
      config: () => presetConfig,
      mode: () => currentMode,
      lastFrame: () => lastFrameDataUrl,
      zen: () => zenActive,
      brightness: () => lastBrightness,
      fieldValue: (status, name) => fieldValue(status, name),
    };
  });
})();
